from fractions import Fraction
sols = set()
for p in range(1, 200):
    for q in range(1, 30):
        r = Fraction(p, q)
        a = Fraction(7) / (1 + r + r * r)
        if sum(a * r ** k for k in range(6)) == 63:
            sols.add(a)
assert len(sols) == 1
print(sols.pop())
